// ConcTypeConstraintTypeConstraintList is the term type of the variadic operator `concTypeConstraint(...)` of sort TypeConstraintList
// (Java's abstract class concTypeConstraint): a maximally-shared cons cell (Java's
// ConsconcTypeConstraint: a head and a tail) or the empty list (Java's EmptyconcTypeConstraint).
type ConcTypeConstraintTypeConstraintList struct {
	head  TypeConstraint
	tail  TypeConstraintList
	empty bool
	hash  uint32
	// children caches the Visitable children (Java's children field)
	children atomic.Pointer[[]any]
}

